        self.expect('SYMBOL', '{')
        fields = []
        while not self.check('SYMBOL', '}'):
            if self.match('SYMBOL', '['):
                key = self.parse_expr()
                self.expect('SYMBOL', ']')
                self.expect('SYMBOL', '=')
                val = self.parse_expr()
                fields.append((key, val))
