                res = _loadstring(val, "(command line)")
                if res[0] is NIL:
                    sys.stderr.write(f"{prog}: {res[1]}\n")
                    sys.exit(1)
                lua_call(res[0], [])
            except LuaError as e:
                sys.stderr.write(f"{prog}: {e}\n")
                sys.exit(1)
