    if v is None: return "nil"
    if isinstance(v, bool): return "boolean"
    if isinstance(v, (int, float)): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, LuaTable): return "table"
    if callable(v) or isinstance(v, LuaClosure): return "function"
    if isinstance(v, LuaUserData): return "userdata"
    if isinstance(v, LuaThread): return "thread"
    return "userdata"

def lua_tostring(v):
    if v is None: return "nil"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float):
        if math.isinf(v): return "inf" if v > 0 else "-inf"
        if math.isnan(v): return "nan"
        if v.is_integer(): return str(int(v))
        return str(v)
    if isinstance(v, str): return v
    if isinstance(v, LuaTable):
        if v.metatable:
            ts = v.metatable.rawget("__tostring")
            if ts is not NIL:
                res = lua_call(ts, [v])
                return lua_tostring(res[0] if res else NIL)
        return repr(v)
    if isinstance(v, LuaClosure) or callable(v):
        return f"function: 0x{id(v):x}"
    if isinstance(v, LuaUserData):
        return f"userdata: 0x{id(v):x}"
    if isinstance(v, LuaThread):
        return f"thread: 0x{id(v):x}"
    return str(v)

def lua_tonumber(v, base=10):
    if isinstance(v, (int, float)): return v
    if isinstance(v, str):
        try:
            s = v.strip()
            if base != 10:
                return int(s, base)
            if s.startswith('0x') or s.startswith('0X'):
                return int(s, 16)
            f = float(s)
            return int(f) if f.is_integer() else f
        except ValueError:
            return NIL
    return NIL

def is_truthy(v):
    return v is not None and v is not False

class LuaTable:
    def __init__(self):
        self.dict = {}
        self.metatable = None

    def _norm_key(self, k):
        if k is None:
            raise LuaError("table index is nil")
        if isinstance(k, float) and math.isnan(k):
            raise LuaError("table index is NaN")
        if isinstance(k, float) and k.is_integer():
            return int(k)
        return k

    def rawget(self, k):
        nk = self._norm_key(k)
        return self.dict.get(nk, NIL)

    def rawset(self, k, v):
        nk = self._norm_key(k)
        if v is NIL:
            self.dict.pop(nk, None)
        else:
            self.dict[nk] = v

    def __repr__(self):
        return f"table: 0x{id(self):x}"

class LuaUserData:
    def __init__(self, val=None):
        self.val = val
        self.metatable = None

class LuaThread:
    def __init__(self, func):
        self.func = func
        self.status = "suspended"
        self.env = None

class LuaClosure:
    def __init__(self, params, is_vararg, body, env):
        self.params = params
        self.is_vararg = is_vararg
        self.body = body
        self.env = env

class Env:
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def get(self, name):
        if name in self.vars:
            return self.vars[name]
        if self.parent:
            return self.parent.get(name)
        return GLOBAL_ENV.rawget(name)

    def set(self, name, val):
        curr = self
        while curr:
            if name in curr.vars:
                curr.vars[name] = val
                return
            curr = curr.parent
        GLOBAL_ENV.rawset(name, val)

    def set_local(self, name, val):
        self.vars[name] = val

GLOBAL_ENV = LuaTable()

def lua_gettable(t, k):
    if isinstance(t, LuaTable):
        val = t.rawget(k)
        if val is not NIL:
            return val
        if t.metatable:
            idx = t.metatable.rawget("__index")
            if idx is not NIL:
                if isinstance(idx, LuaTable):
                    return lua_gettable(idx, k)
                elif callable(idx) or isinstance(idx, LuaClosure):
                    res = lua_call(idx, [t, k])
                    return res[0] if res else NIL
        return NIL
    elif isinstance(t, str):
        str_lib = GLOBAL_ENV.rawget("string")
        if isinstance(str_lib, LuaTable):
            return str_lib.rawget(k)
        return NIL
    else:
        raise LuaError(f"attempt to index a {lua_type(t)} value")

def lua_settable(t, k, v):
    if isinstance(t, LuaTable):
        nk = t._norm_key(k)
        if nk in t.dict:
            t.rawset(k, v)
            return
        if t.metatable:
            nidx = t.metatable.rawget("__newindex")
            if nidx is not NIL:
                if isinstance(nidx, LuaTable):
                    lua_settable(nidx, k, v)
                    return
                elif callable(nidx) or isinstance(nidx, LuaClosure):
                    lua_call(nidx, [t, k, v])
                    return
        t.rawset(k, v)
    else:
        raise LuaError(f"attempt to index a {lua_type(t)} value")

def lua_call(func, args):
    if isinstance(func, LuaClosure):
        new_env = Env(func.env)
        for i, param in enumerate(func.params):
            val = args[i] if i < len(args) else NIL
            new_env.set_local(param, val)
        if func.is_vararg:
            varargs = args[len(func.params):]
            new_env.set_local("...", varargs)
        else:
            new_env.set_local("...", [])
        evaluator = Evaluator(new_env)
        try:
            evaluator.eval_block(func.body)
            return []
        except LuaReturn as ret:
            return ret.values
    elif callable(func):
        res = func(*args)
        if res is None:
            return []
        if isinstance(res, tuple):
            return list(res)
        if isinstance(res, list):
            return res
        return [res]
    elif isinstance(func, LuaTable):
        if func.metatable:
            c = func.metatable.rawget("__call")
            if c is not NIL:
                return lua_call(c, [func] + list(args))
        raise LuaError(f"attempt to call a {lua_type(func)} value")
    else:
        raise LuaError(f"attempt to call a {lua_type(func)} value")

# --- LEXER ---
KEYWORDS = {
    'and', 'break', 'do', 'else', 'elseif', 'end', 'false', 'for',
    'function', 'if', 'in', 'local', 'nil', 'not', 'or', 'repeat',
    'return', 'then', 'true', 'until', 'while'
}

class Lexer:
    def __init__(self, text, filename="<string>"):
        self.text = text
        self.filename = filename
        self.pos = 0
        self.line = 1
        self.col = 1
        self.length = len(text)

    def error(self, msg):
        raise LuaError(f"{self.filename}:{self.line}: {msg}", self.line)

    def peek(self, n=0):
        p = self.pos + n
        return self.text[p] if p < self.length else ''

    def next_token(self):
        while self.pos < self.length:
            ch = self.text[self.pos]
            if ch in ' \t\r\n\f':
                if ch == '\n':
                    self.line += 1
                    self.col = 1
                else:
                    self.col += 1
                self.pos += 1
                continue

            if ch == '-' and self.peek(1) == '-':
                self.pos += 2
                self.col += 2
                if self.peek() == '[':
                    m = re.match(r'\[(=*)\[', self.text[self.pos:])
                    if m:
                        eq = m.group(1)
                        close_pat = ']' + eq + ']'
                        end_pos = self.text.find(close_pat, self.pos + len(m.group(0)))
                        if end_pos == -1:
                            self.error("unfinished long comment")
                        comment_text = self.text[self.pos:end_pos + len(close_pat)]
                        self.line += comment_text.count('\n')
                        self.pos = end_pos + len(close_pat)
                        continue
                while self.pos < self.length and self.text[self.pos] != '\n':
                    self.pos += 1
                continue

            if ch in '\'"':
                quote = ch
                start_line = self.line
                self.pos += 1
                buf = []
                while self.pos < self.length:
                    c = self.text[self.pos]
                    if c == quote:
                        self.pos += 1
                        return ('STRING', ''.join(buf), start_line)
                    elif c == '\\':
                        self.pos += 1
                        if self.pos >= self.length:
                            self.error("unfinished string")
                        nc = self.text[self.pos]
                        if nc == 'n': buf.append('\n')
                        elif nc == 't': buf.append('\t')
                        elif nc == 'r': buf.append('\r')
                        elif nc == 'a': buf.append('\a')
                        elif nc == 'b': buf.append('\b')
                        elif nc == 'f': buf.append('\f')
                        elif nc == 'v': buf.append('\v')
                        elif nc == '\\': buf.append('\\')
                        elif nc == '"': buf.append('"')
                        elif nc == "'": buf.append("'")
                        elif nc == '\n': buf.append('\n'); self.line += 1
                        elif nc == 'z':
                            self.pos += 1
                            while self.pos < self.length and self.text[self.pos] in ' \t\r\n\f':
                                if self.text[self.pos] == '\n': self.line += 1
                                self.pos += 1
                            continue
                        elif nc.isdigit():
                            m = re.match(r'\d{1,3}', self.text[self.pos:])
                            dstr = m.group(0)
                            self.pos += len(dstr) - 1
                            buf.append(chr(int(dstr)))
                        elif nc == 'x':
                            m = re.match(r'x[0-9a-fA-F]{2}', self.text[self.pos:])
                            if not m: self.error("invalid hex escape sequence")
                            self.pos += 2
                            buf.append(chr(int(m.group(0)[1:], 16)))
                        else:
                            buf.append(nc)
                        self.pos += 1
                    elif c == '\n':
                        self.error("unfinished string")
                    else:
                        buf.append(c)
                        self.pos += 1
                self.error("unfinished string")

            if ch == '[' and (self.peek(1) == '[' or self.peek(1) == '='):
                m = re.match(r'\[(=*)\[', self.text[self.pos:])
                if m:
                    eq = m.group(1)
                    close_pat = ']' + eq + ']'
                    start_line = self.line
                    self.pos += len(m.group(0))
                    if self.pos < self.length and self.text[self.pos] == '\n':
                        self.pos += 1
                        self.line += 1
                    elif self.pos + 1 < self.length and self.text[self.pos:self.pos+2] == '\r\n':
                        self.pos += 2
                        self.line += 1
                    end_pos = self.text.find(close_pat, self.pos)
                    if end_pos == -1:
                        self.error("unfinished long string")
                    val = self.text[self.pos:end_pos]
                    self.line += val.count('\n')
                    self.pos = end_pos + len(close_pat)
                    return ('STRING', val, start_line)

            if ch.isdigit() or (ch == '.' and self.peek(1).isdigit()):
                start_line = self.line
                if self.text.startswith('0x', self.pos) or self.text.startswith('0X', self.pos):
                    m = re.match(r'0[xX][0-9a-fA-F]+(\.[0-9a-fA-F]+)?([pP][+-]?[0-9]+)?', self.text[self.pos:])
                    if m:
                        s = m.group(0)
                        self.pos += len(s)
                        if '.' in s or 'p' in s or 'P' in s:
                            val = float.fromhex(s)
                        else:
                            val = int(s, 16)
                        return ('NUMBER', val, start_line)
                m = re.match(r'(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?', self.text[self.pos:])
                if m:
                    s = m.group(0)
                    self.pos += len(s)
                    val = float(s) if ('.' in s or 'e' in s or 'E' in s) else int(s)
                    return ('NUMBER', val, start_line)

            if ch.isalpha() or ch == '_':
                m = re.match(r'[a-zA-Z_][a-zA-Z0-9_]*', self.text[self.pos:])
                s = m.group(0)
                start_line = self.line
                self.pos += len(s)
                if s in KEYWORDS:
                    return ('KEYWORD', s, start_line)
                return ('NAME', s, start_line)

            if self.pos + 2 < self.length:
                s3 = self.text[self.pos:self.pos+3]
                if s3 == '...':
                    self.pos += 3
                    return ('SYMBOL', '...', self.line)

            if self.pos + 1 < self.length:
                s2 = self.text[self.pos:self.pos+2]
                if s2 in ('==', '~=', '<=', '>=', '..'):
                    self.pos += 2
                    return ('SYMBOL', s2, self.line)

            if ch in '+-*/%^#=<>()[]{},;:.:':
                self.pos += 1
                return ('SYMBOL', ch, self.line)

            self.error(f"unexpected symbol near '{ch}'")

        return ('EOF', '', self.line)

# --- AST NODES ---
class BlockNode:
    def __init__(self, stats): self.stats = stats
class LocalAssignNode:
    def __init__(self, names, exprs): self.names = names; self.exprs = exprs
class AssignNode:
    def __init__(self, targets, exprs): self.targets = targets; self.exprs = exprs
class LocalFuncNode:
    def __init__(self, name, params, is_vararg, body):
        self.name = name; self.params = params; self.is_vararg = is_vararg; self.body = body
class FuncStatNode:
    def __init__(self, name_node, params, is_vararg, body):
        self.name_node = name_node; self.params = params; self.is_vararg = is_vararg; self.body = body
class IfNode:
    def __init__(self, cond_blocks, else_block):
        self.cond_blocks = cond_blocks; self.else_block = else_block
class WhileNode:
    def __init__(self, cond, body): self.cond = cond; self.body = body
class RepeatNode:
    def __init__(self, body, cond): self.body = body; self.cond = cond
class ForNumNode:
    def __init__(self, var_name, start, stop, step, body):
        self.var_name = var_name; self.start = start; self.stop = stop; self.step = step; self.body = body
class ForInNode:
    def __init__(self, names, exprs, body):
        self.names = names; self.exprs = exprs; self.body = body
class DoNode:
    def __init__(self, body): self.body = body
class ReturnNode:
    def __init__(self, exprs): self.exprs = exprs
class BreakNode: pass
class ExprStmtNode:
    def __init__(self, expr): self.expr = expr

class LiteralNode:
    def __init__(self, val): self.val = val
class VarargNode: pass
class VarNode:
    def __init__(self, name): self.name = name
class IndexNode:
    def __init__(self, obj, key): self.obj = obj; self.key = key
class CallNode:
    def __init__(self, func, args): self.func = func; self.args = args
class MethodCallNode:
    def __init__(self, obj, method, args): self.obj = obj; self.method = method; self.args = args
class TableCtorNode:
    def __init__(self, fields): self.fields = fields
class FuncDefNode:
    def __init__(self, params, is_vararg, body):
        self.params = params; self.is_vararg = is_vararg; self.body = body
class UnaryOpNode:
    def __init__(self, op, expr): self.op = op; self.expr = expr
class BinOpNode:
    def __init__(self, op, left, right): self.op = op; self.left = left; self.right = right

# --- PARSER ---
class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.cur = None
        self.advance()

    def error(self, msg):
        tok_val = self.cur[1] if self.cur[0] != 'EOF' else '<eof>'
        raise LuaError(f"{self.lexer.filename}:{self.cur[2]}: {msg} near '{tok_val}'", self.cur[2])

    def advance(self):
        self.cur = self.lexer.next_token()

    def check(self, kind, val=None):
        if self.cur[0] != kind: return False
        if val is not None and self.cur[1] != val: return False
        return True

    def match(self, kind, val=None):
        if self.check(kind, val):
            self.advance()
            return True
        return False

    def expect(self, kind, val=None):
        if not self.check(kind, val):
            expected = val if val else kind
            self.error(f"expected '{expected}'")
        self.advance()

    def parse_block(self):
        stats = []
        while not self.check('EOF') and not self.check('KEYWORD', 'end') and \
              not self.check('KEYWORD', 'else') and not self.check('KEYWORD', 'elseif') and \
              not self.check('KEYWORD', 'until'):
            st = self.parse_stat()
            if st is not None:
                stats.append(st)
                if isinstance(st, (ReturnNode, BreakNode)):
                    self.match('SYMBOL', ';')
                    break
            self.match('SYMBOL', ';')
        return BlockNode(stats)

    def parse_stat(self):
        if self.match('KEYWORD', 'if'):
            return self.parse_if()
        elif self.match('KEYWORD', 'while'):
            return self.parse_while()
        elif self.match('KEYWORD', 'repeat'):
            return self.parse_repeat()
        elif self.match('KEYWORD', 'for'):
            return self.parse_for()
        elif self.match('KEYWORD', 'do'):
            body = self.parse_block()
            self.expect('KEYWORD', 'end')
            return DoNode(body)
        elif self.match('KEYWORD', 'return'):
            exprs = []
            if not self.check('KEYWORD', 'end') and not self.check('KEYWORD', 'else') and \
               not self.check('KEYWORD', 'elseif') and not self.check('KEYWORD', 'until') and \
               not self.check('SYMBOL', ';') and not self.check('EOF'):
                exprs = self.parse_explist()
            return ReturnNode(exprs)
        elif self.match('KEYWORD', 'break'):
            return BreakNode()
        elif self.match('KEYWORD', 'local'):
            if self.match('KEYWORD', 'function'):
                name = self.cur[1]
                self.expect('NAME')
                params, is_vararg, body = self.parse_funcbody()
                return LocalFuncNode(name, params, is_vararg, body)
            else:
                names = [self.cur[1]]
                self.expect('NAME')
                while self.match('SYMBOL', ','):
                    names.append(self.cur[1])
                    self.expect('NAME')
                exprs = []
                if self.match('SYMBOL', '='):
                    exprs = self.parse_explist()
                return LocalAssignNode(names, exprs)
        elif self.match('KEYWORD', 'function'):
            name_node = self.parse_funcname()
            params, is_vararg, body = self.parse_funcbody()
            return FuncStatNode(name_node, params, is_vararg, body)
        else:
            exp = self.parse_prefixexp()
            if self.check('SYMBOL', ',') or self.check('SYMBOL', '='):
                targets = [exp]
                while self.match('SYMBOL', ','):
                    targets.append(self.parse_prefixexp())
                self.expect('SYMBOL', '=')
                exprs = self.parse_explist()
                return AssignNode(targets, exprs)
            elif isinstance(exp, (CallNode, MethodCallNode)):
                return ExprStmtNode(exp)
            else:
                self.error("syntax error")

    def parse_if(self):
        cond_blocks = []
        cond = self.parse_expr()
        self.expect('KEYWORD', 'then')
        body = self.parse_block()
        cond_blocks.append((cond, body))
        while self.match('KEYWORD', 'elseif'):
            cond = self.parse_expr()
            self.expect('KEYWORD', 'then')
            body = self.parse_block()
            cond_blocks.append((cond, body))
        else_block = None
        if self.match('KEYWORD', 'else'):
            else_block = self.parse_block()
        self.expect('KEYWORD', 'end')
        return IfNode(cond_blocks, else_block)

    def parse_while(self):
        cond = self.parse_expr()
        self.expect('KEYWORD', 'do')
        body = self.parse_block()
        self.expect('KEYWORD', 'end')
        return WhileNode(cond, body)

    def parse_repeat(self):
        body = self.parse_block()
        self.expect('KEYWORD', 'until')
        cond = self.parse_expr()
        return RepeatNode(body, cond)

    def parse_for(self):
        var_name = self.cur[1]
        self.expect('NAME')
        if self.match('SYMBOL', '='):
            start = self.parse_expr()
            self.expect('SYMBOL', ',')
            stop = self.parse_expr()
            step = LiteralNode(1)
            if self.match('SYMBOL', ','):
                step = self.parse_expr()
            self.expect('KEYWORD', 'do')
            body = self.parse_block()
            self.expect('KEYWORD', 'end')
            return ForNumNode(var_name, start, stop, step, body)
        else:
            names = [var_name]
            while self.match('SYMBOL', ','):
                names.append(self.cur[1])
                self.expect('NAME')
            self.expect('KEYWORD', 'in')
            exprs = self.parse_explist()
            self.expect('KEYWORD', 'do')
            body = self.parse_block()
            self.expect('KEYWORD', 'end')
            return ForInNode(names, exprs, body)

    def parse_funcname(self):
        name = self.cur[1]
        self.expect('NAME')
        node = VarNode(name)
        while self.match('SYMBOL', '.'):
            field = self.cur[1]
            self.expect('NAME')
            node = IndexNode(node, LiteralNode(field))
        if self.match('SYMBOL', ':'):
            method = self.cur[1]
            self.expect('NAME')
            node = ('method', node, method)
        return node

    def parse_funcbody(self):
        self.expect('SYMBOL', '(')
        params = []
        is_vararg = False
        if not self.check('SYMBOL', ')'):
            if self.match('SYMBOL', '...'):
                is_vararg = True
            else:
                params.append(self.cur[1])
                self.expect('NAME')
                while self.match('SYMBOL', ','):
                    if self.match('SYMBOL', '...'):
                        is_vararg = True
                        break
                    params.append(self.cur[1])
                    self.expect('NAME')
        self.expect('SYMBOL', ')')
        body = self.parse_block()
        self.expect('KEYWORD', 'end')
        return params, is_vararg, body

    def parse_explist(self):
        exprs = [self.parse_expr()]
        while self.match('SYMBOL', ','):
            exprs.append(self.parse_expr())
        return exprs

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        node = self.parse_and()
        while self.match('KEYWORD', 'or'):
            right = self.parse_and()
            node = BinOpNode('or', node, right)
        return node

    def parse_and(self):
        node = self.parse_rel()
        while self.match('KEYWORD', 'and'):
            right = self.parse_rel()
            node = BinOpNode('and', node, right)
        return node

    def parse_rel(self):
        node = self.parse_concat()
        while self.check('SYMBOL') and self.cur[1] in ('<', '>', '<=', '>=', '~=', '=='):
            op = self.cur[1]
            self.advance()
            right = self.parse_concat()
            node = BinOpNode(op, node, right)
        return node

    def parse_concat(self):
        node = self.parse_add()
        if self.match('SYMBOL', '..'):
            right = self.parse_concat()
            node = BinOpNode('..', node, right)
        return node

    def parse_add(self):
        node = self.parse_mul()
        while self.check('SYMBOL') and self.cur[1] in ('+', '-'):
            op = self.cur[1]
            self.advance()
            right = self.parse_mul()
            node = BinOpNode(op, node, right)
        return node

    def parse_mul(self):
        node = self.parse_unary()
        while self.check('SYMBOL') and self.cur[1] in ('*', '/', '%'):
            op = self.cur[1]
            self.advance()
            right = self.parse_unary()
            node = BinOpNode(op, node, right)
        return node

    def parse_unary(self):
        if self.check('KEYWORD', 'not') or (self.check('SYMBOL') and self.cur[1] in ('-', '#')):
            op = self.cur[1]
            self.advance()
            expr = self.parse_unary()
            return UnaryOpNode(op, expr)
        return self.parse_pow()

    def parse_pow(self):
        node = self.parse_primary()
        if self.match('SYMBOL', '^'):
            right = self.parse_pow()
            node = BinOpNode('^', node, right)
        return node

    def parse_primary(self):
        if self.check('NIL') or self.check('KEYWORD', 'nil'):
            self.advance(); return LiteralNode(NIL)
        elif self.check('KEYWORD', 'false'):
            self.advance(); return LiteralNode(False)
        elif self.check('KEYWORD', 'true'):
            self.advance(); return LiteralNode(True)
        elif self.check('NUMBER'):
            val = self.cur[1]; self.advance(); return LiteralNode(val)
        elif self.check('STRING'):
            val = self.cur[1]; self.advance(); return LiteralNode(val)
        elif self.check('SYMBOL', '...'):
            self.advance(); return VarargNode()
        elif self.check('SYMBOL', '{'):
            return self.parse_tablector()
        elif self.match('KEYWORD', 'function'):
            params, is_vararg, body = self.parse_funcbody()
            return FuncDefNode(params, is_vararg, body)
        else:
            return self.parse_prefixexp()

    def parse_tablector(self):
        self.expect('SYMBOL', '{')
        fields = []
        while not self.check('SYMBOL', '}'):
            if self.match('SYMBOL', '['):
                key = self.parse_expr()
                self.expect('SYMBOL', ']')
                self.expect('SYMBOL', '=')
                val = self.parse_expr()
                fields.append((key, val))
            elif self.check('NAME') and self.lexer.peek() == '=':
                name = self.cur[1]
                self.advance()
                self.expect('SYMBOL', '=')
                val = self.parse_expr()
                fields.append((LiteralNode(name), val))
            else:
                val = self.parse_expr()
                fields.append((None, val))
            if not self.match('SYMBOL', ',') and not self.match('SYMBOL', ';'):
                break
        self.expect('SYMBOL', '}')
        return TableCtorNode(fields)

    def parse_prefixexp(self):
        if self.match('SYMBOL', '('):
            node = self.parse_expr()
            self.expect('SYMBOL', ')')
        elif self.check('NAME'):
            node = VarNode(self.cur[1])
            self.advance()
        else:
            self.error("unexpected symbol")

        while True:
            if self.match('SYMBOL', '['):
                key = self.parse_expr()
                self.expect('SYMBOL', ']')
                node = IndexNode(node, key)
            elif self.match('SYMBOL', '.'):
                field = self.cur[1]
                self.expect('NAME')
                node = IndexNode(node, LiteralNode(field))
            elif self.match('SYMBOL', ':'):
                method = self.cur[1]
                self.expect('NAME')
                args = self.parse_args()
                node = MethodCallNode(node, method, args)
            elif self.check('SYMBOL', '(') or self.check('SYMBOL', '{') or self.check('STRING'):
                args = self.parse_args()
                node = CallNode(node, args)
            else:
                break
        return node

    def parse_args(self):
        if self.match('SYMBOL', '('):
            args = []
            if not self.check('SYMBOL', ')'):
                args = self.parse_explist()
            self.expect('SYMBOL', ')')
            return args
        elif self.check('SYMBOL', '{'):
            return [self.parse_tablector()]
        elif self.check('STRING'):
            val = self.cur[1]
            self.advance()
            return [LiteralNode(val)]
        else:
            self.error("function arguments expected")

# --- EVALUATOR ---
class Evaluator:
    def __init__(self, env):
        self.env = env

    def eval_block(self, block):
        for stat in block.stats:
            self.eval_stat(stat)

    def eval_stat(self, stat):
        if isinstance(stat, LocalAssignNode):
            vals = self.eval_explist_multi(stat.exprs)
            for i, name in enumerate(stat.names):
                v = vals[i] if i < len(vals) else NIL
                self.env.set_local(name, v)
        elif isinstance(stat, AssignNode):
            rhs_vals = self.eval_explist_multi(stat.exprs)
            # Evaluate left hand targets
            targets = []
            for target_node in stat.targets:
                if isinstance(target_node, VarNode):
                    targets.append(('var', target_node.name))
                elif isinstance(target_node, IndexNode):
                    obj = self.eval_expr_single(target_node.obj)
                    key = self.eval_expr_single(target_node.key)
                    targets.append(('index', obj, key))
            for i, target in enumerate(targets):
                val = rhs_vals[i] if i < len(rhs_vals) else NIL
                if target[0] == 'var':
                    self.env.set(target[1], val)
                else:
                    lua_settable(target[1], target[2], val)
        elif isinstance(stat, LocalFuncNode):
            closure = LuaClosure(stat.params, stat.is_vararg, stat.body, self.env)
            self.env.set_local(stat.name, closure)
        elif isinstance(stat, FuncStatNode):
            closure = LuaClosure(stat.params, stat.is_vararg, stat.body, self.env)
            name_node = stat.name_node
            if isinstance(name_node, tuple) and name_node[0] == 'method':
                # function t:m()
                closure.params = ['self'] + closure.params
                obj_node = name_node[1]
                method_name = name_node[2]
                obj = self.eval_expr_single(obj_node)
                lua_settable(obj, method_name, closure)
            elif isinstance(name_node, VarNode):
                self.env.set(name_node.name, closure)
            elif isinstance(name_node, IndexNode):
                obj = self.eval_expr_single(name_node.obj)
                key = self.eval_expr_single(name_node.key)
                lua_settable(obj, key, closure)
        elif isinstance(stat, IfNode):
            executed = False
            for cond_node, body in stat.cond_blocks:
                cond_val = self.eval_expr_single(cond_node)
                if is_truthy(cond_val):
                    self.eval_block(body)
                    executed = True
                    break
            if not executed and stat.else_block:
                self.eval_block(stat.else_block)
        elif isinstance(stat, WhileNode):
            while is_truthy(self.eval_expr_single(stat.cond)):
                try:
                    self.eval_block(stat.body)
                except LuaBreak:
                    break
        elif isinstance(stat, RepeatNode):
            while True:
                try:
                    self.eval_block(stat.body)
                except LuaBreak:
                    break
                if is_truthy(self.eval_expr_single(stat.cond)):
                    break
        elif isinstance(stat, ForNumNode):
            start = float(self.eval_expr_single(stat.start))
            stop = float(self.eval_expr_single(stat.stop))
            step = float(self.eval_expr_single(stat.step))
            curr = start
            while (step > 0 and curr <= stop) or (step < 0 and curr >= stop):
                loop_env = Env(self.env)
                loop_env.set_local(stat.var_name, int(curr) if curr.is_integer() else curr)
                sub_eval = Evaluator(loop_env)
                try:
                    sub_eval.eval_block(stat.body)
                except LuaBreak:
                    break
                curr += step
        elif isinstance(stat, ForInNode):
            vals = self.eval_explist_multi(stat.exprs)
            iter_func = vals[0] if len(vals) > 0 else NIL
            state = vals[1] if len(vals) > 1 else NIL
            var_val = vals[2] if len(vals) > 2 else NIL
            while True:
                res = lua_call(iter_func, [state, var_val])
                if not res or res[0] is NIL:
                    break
                var_val = res[0]
                loop_env = Env(self.env)
                for i, name in enumerate(stat.names):
                    v = res[i] if i < len(res) else NIL
                    loop_env.set_local(name, v)
                sub_eval = Evaluator(loop_env)
                try:
                    sub_eval.eval_block(stat.body)
                except LuaBreak:
                    break
        elif isinstance(stat, DoNode):
            self.eval_block(stat.body)
        elif isinstance(stat, ReturnNode):
            vals = self.eval_explist_multi(stat.exprs)
            raise LuaReturn(vals)
        elif isinstance(stat, BreakNode):
            raise LuaBreak()
        elif isinstance(stat, ExprStmtNode):
            self.eval_expr_multi(stat.expr)

    def eval_expr_single(self, expr_node):
        res = self.eval_expr_multi(expr_node)
        return res[0] if res else NIL

    def eval_explist_multi(self, expr_nodes):
        if not expr_nodes: return []
        results = []
        for i, node in enumerate(expr_nodes):
            if i == len(expr_nodes) - 1:
                results.extend(self.eval_expr_multi(node))
            else:
                results.append(self.eval_expr_single(node))
        return results

    def eval_expr_multi(self, node):
        if isinstance(node, LiteralNode):
            return [node.val]
        elif isinstance(node, VarargNode):
            v = self.env.get("...")
            return list(v) if isinstance(v, list) else []
        elif isinstance(node, VarNode):
            return [self.env.get(node.name)]
        elif isinstance(node, IndexNode):
            obj = self.eval_expr_single(node.obj)
            key = self.eval_expr_single(node.key)
            return [lua_gettable(obj, key)]
        elif isinstance(node, CallNode):
            func = self.eval_expr_single(node.func)
            args = self.eval_explist_multi(node.args)
            return lua_call(func, args)
        elif isinstance(node, MethodCallNode):
            obj = self.eval_expr_single(node.obj)
            method = lua_gettable(obj, node.method)
            args = self.eval_explist_multi(node.args)
            return lua_call(method, [obj] + args)
        elif isinstance(node, TableCtorNode):
            t = LuaTable()
            array_idx = 1
            for i, (key_node, val_node) in enumerate(node.fields):
                if key_node is not None:
                    k = self.eval_expr_single(key_node)
                    v = self.eval_expr_single(val_node)
                    lua_settable(t, k, v)
                else:
                    if i == len(node.fields) - 1:
                        vals = self.eval_expr_multi(val_node)
                        for v in vals:
                            lua_settable(t, array_idx, v)
                            array_idx += 1
                    else:
                        v = self.eval_expr_single(val_node)
                        lua_settable(t, array_idx, v)
                        array_idx += 1
            return [t]
        elif isinstance(node, FuncDefNode):
            closure = LuaClosure(node.params, node.is_vararg, node.body, self.env)
            return [closure]
        elif isinstance(node, UnaryOpNode):
            v = self.eval_expr_single(node.expr)
            if node.op == '-':
                if isinstance(v, (int, float)):
                    return [-v]
                raise LuaError(f"attempt to perform arithmetic on a {lua_type(v)} value")
            elif node.op == 'not':
                return [not is_truthy(v)]
            elif node.op == '#':
                if isinstance(v, str):
                    return [len(v)]
                elif isinstance(v, LuaTable):
                    if v.metatable:
                        l_fn = v.metatable.rawget("__len")
                        if l_fn is not NIL:
                            res = lua_call(l_fn, [v])
                            return [res[0] if res else 0]
                    idx = 1
                    while v.rawget(idx) is not NIL:
                        idx += 1
                    return [idx - 1]
                raise LuaError(f"attempt to get length of a {lua_type(v)} value")
        elif isinstance(node, BinOpNode):
            l = self.eval_expr_single(node.left)
            if node.op == 'and':
                if not is_truthy(l): return [l]
                return [self.eval_expr_single(node.right)]
            elif node.op == 'or':
                if is_truthy(l): return [l]
                return [self.eval_expr_single(node.right)]
            r = self.eval_expr_single(node.right)
            if node.op == '+':
                ln, rn = lua_tonumber(l), lua_tonumber(r)
                if ln is not None and rn is not None:
                    res = ln + rn
                    return [int(res) if isinstance(res, float) and res.is_integer() else res]
                raise LuaError("attempt to perform arithmetic")
            elif node.op == '-':
                ln, rn = lua_tonumber(l), lua_tonumber(r)
                if ln is not None and rn is not None:
                    res = ln - rn
                    return [int(res) if isinstance(res, float) and res.is_integer() else res]
                raise LuaError("attempt to perform arithmetic")
            elif node.op == '*':
                ln, rn = lua_tonumber(l), lua_tonumber(r)
                if ln is not None and rn is not None:
                    res = ln * rn
                    return [int(res) if isinstance(res, float) and res.is_integer() else res]
                raise LuaError("attempt to perform arithmetic")
            elif node.op == '/':
                ln, rn = lua_tonumber(l), lua_tonumber(r)
                if ln is not None and rn is not None:
                    res = float(ln) / float(rn)
                    return [int(res) if res.is_integer() else res]
                raise LuaError("attempt to perform arithmetic")
            elif node.op == '%':
                ln, rn = lua_tonumber(l), lua_tonumber(r)
                if ln is not None and rn is not None:
                    res = float(ln) % float(rn)
                    return [int(res) if res.is_integer() else res]
                raise LuaError("attempt to perform arithmetic")
            elif node.op == '^':
                ln, rn = lua_tonumber(l), lua_tonumber(r)
                if ln is not None and rn is not None:
                    res = float(ln) ** float(rn)
                    return [int(res) if res.is_integer() else res]
                raise LuaError("attempt to perform arithmetic")
            elif node.op == '..':
                ls, rs = lua_tostring(l), lua_tostring(r)
                return [ls + rs]
            elif node.op == '==':
                return [l == r]
            elif node.op == '~=':
                return [l != r]
            elif node.op == '<':
                return [l < r]
            elif node.op == '>':
                return [l > r]
            elif node.op == '<=':
                return [l <= r]
            elif node.op == '>=':
                return [l >= r]
        return [NIL]

# --- INIT STANDARD LIBRARIES ---
def init_stdlib():
    def _print(*args):
        sys.stdout.write('\t'.join(lua_tostring(a) for a in args) + '\n')
        sys.stdout.flush()

    def _type(v=NIL): return lua_type(v)
    def _tostring(v=NIL): return lua_tostring(v)
    def _tonumber(v=NIL, base=10): return lua_tonumber(v, base)
    def _assert(v=NIL, *msg):
        if not is_truthy(v):
            m = msg[0] if msg else "assertion failed!"
            raise LuaError(m)
        return [v] + list(msg)

    def _error(msg=NIL, level=1):
        raise LuaError(lua_tostring(msg))

    def _pcall(f=NIL, *args):
        try:
            res = lua_call(f, args)
            return [True] + res
        except LuaError as e:
            return [False, str(e)]
        except Exception as e:
            return [False, str(e)]

    def _xpcall(f=NIL, err_h=NIL):
        try:
            res = lua_call(f, [])
            return [True] + res
        except LuaError as e:
            h_res = lua_call(err_h, [str(e)])
            return [False, h_res[0] if h_res else str(e)]

    def _pairs(t=NIL):
        if isinstance(t, LuaTable):
            if t.metatable:
                p = t.metatable.rawget("__pairs")
                if p is not NIL:
                    return lua_call(p, [t])
            def _next_func(tbl, k=NIL):
                keys = list(tbl.dict.keys())
                if k is NIL:
                    if keys: return [keys[0], tbl.dict[keys[0]]]
                    return []
                try:
                    idx = keys.index(k)
                    if idx + 1 < len(keys):
                        nk = keys[idx + 1]
                        return [nk, tbl.dict[nk]]
                except ValueError:
                    pass
                return []
            return [_next_func, t, NIL]
        raise LuaError("bad argument #1 to 'pairs'")

    def _ipairs(t=NIL):
        if isinstance(t, LuaTable):
            def _ipairs_aux(tbl, i):
                next_i = i + 1
                v = lua_gettable(tbl, next_i)
                if v is not NIL:
                    return [next_i, v]
                return []
            return [_ipairs_aux, t, 0]
        raise LuaError("bad argument #1 to 'ipairs'")

    def _next(t=NIL, k=NIL):
        if isinstance(t, LuaTable):
            keys = list(t.dict.keys())
            if k is NIL:
                if keys: return [keys[0], t.dict[keys[0]]]
                return []
            try:
                idx = keys.index(k)
                if idx + 1 < len(keys):
                    nk = keys[idx + 1]
                    return [nk, t.dict[nk]]
            except ValueError:
                pass
            return []
        raise LuaError("bad argument #1 to 'next'")

    def _select(n=NIL, *args):
        if n == "#": return [len(args)]
        idx = int(n)
        if idx > 0: return list(args[idx-1:])
        raise LuaError("bad argument #1 to 'select'")

    def _unpack(t=NIL, i=1, j=NIL):
        if isinstance(t, LuaTable):
            if j is NIL:
                j = 0
                while t.rawget(j + 1) is not NIL:
                    j += 1
            res = []
            for k in range(int(i), int(j) + 1):
                res.append(t.rawget(k))
            return res
        raise LuaError("bad argument #1 to 'unpack'")

    def _setmetatable(t=NIL, mt=NIL):
        if isinstance(t, LuaTable):
            if t.metatable and t.metatable.rawget("__metatable") is not NIL:
                raise LuaError("cannot change a protected metatable")
            t.metatable = mt if isinstance(mt, LuaTable) else None
            return [t]
        raise LuaError("bad argument #1 to 'setmetatable'")

    def _getmetatable(t=NIL):
        mt = None
        if isinstance(t, LuaTable): mt = t.metatable
        elif isinstance(t, LuaUserData): mt = t.metatable
        if mt:
            prot = mt.rawget("__metatable")
            if prot is not NIL: return [prot]
            return [mt]
        return [NIL]

    def _rawget(t=NIL, k=NIL):
        if isinstance(t, LuaTable): return [t.rawget(k)]
        raise LuaError("bad argument #1 to 'rawget'")

    def _rawset(t=NIL, k=NIL, v=NIL):
        if isinstance(t, LuaTable):
            t.rawset(k, v)
            return [t]
        raise LuaError("bad argument #1 to 'rawset'")

    def _rawequal(v1=NIL, v2=NIL): return [v1 == v2]

    def _loadstring(s=NIL, chunkname="<string>"):
        if isinstance(s, str):
            try:
                lexer = Lexer(s, chunkname)
                parser = Parser(lexer)
                block = parser.parse_block()
                closure = LuaClosure([], True, block, Env(None))
                return [closure]
            except LuaError as e:
                return [NIL, str(e)]
        return [NIL, "string expected"]

    def _loadfile(filename=NIL):
        fname = filename if filename else "<stdin>"
        try:
            if filename:
                with open(filename, 'r', encoding='utf-8', errors='replace') as f:
                    content = f.read()
            else:
                content = sys.stdin.read()
            return _loadstring(content, f"@{fname}")
        except Exception as e:
            return [NIL, str(e)]

    def _dofile(filename=NIL):
        res = _loadfile(filename)
        if res[0] is NIL: raise LuaError(res[1])
        return lua_call(res[0], [])

    def _collectgarbage(opt="collect", arg=NIL):
        return [0]

    def _getfenv(f=1): return [GLOBAL_ENV]
    def _setfenv(f=NIL, env=NIL): return [f]

    # Global bindings
    GLOBAL_ENV.rawset("print", _print)
    GLOBAL_ENV.rawset("type", _type)
    GLOBAL_ENV.rawset("tostring", _tostring)
    GLOBAL_ENV.rawset("tonumber", _tonumber)
    GLOBAL_ENV.rawset("assert", _assert)
    GLOBAL_ENV.rawset("error", _error)
    GLOBAL_ENV.rawset("pcall", _pcall)
    GLOBAL_ENV.rawset("xpcall", _xpcall)
    GLOBAL_ENV.rawset("pairs", _pairs)
    GLOBAL_ENV.rawset("ipairs", _ipairs)
    GLOBAL_ENV.rawset("next", _next)
    GLOBAL_ENV.rawset("select", _select)
    GLOBAL_ENV.rawset("unpack", _unpack)
    GLOBAL_ENV.rawset("setmetatable", _setmetatable)
    GLOBAL_ENV.rawset("getmetatable", _getmetatable)
    GLOBAL_ENV.rawset("rawget", _rawget)
    GLOBAL_ENV.rawset("rawset", _rawset)
    GLOBAL_ENV.rawset("rawequal", _rawequal)
    GLOBAL_ENV.rawset("loadstring", _loadstring)
    GLOBAL_ENV.rawset("load", _loadstring)
    GLOBAL_ENV.rawset("loadfile", _loadfile)
    GLOBAL_ENV.rawset("dofile", _dofile)
    GLOBAL_ENV.rawset("collectgarbage", _collectgarbage)
    GLOBAL_ENV.rawset("getfenv", _getfenv)
    GLOBAL_ENV.rawset("setfenv", _setfenv)
    GLOBAL_ENV.rawset("_VERSION", LUA_VERSION)
    GLOBAL_ENV.rawset("_G", GLOBAL_ENV)

    # String library
    str_lib = LuaTable()
    str_lib.rawset("sub", lambda s="", i=1, j=-1: s[int(i)-1: int(j) if int(j) != -1 else None])
    str_lib.rawset("len", lambda s="": len(s))
    str_lib.rawset("byte", lambda s="", i=1, j=NIL: [ord(c) for c in s[int(i)-1 : (int(i) if j is NIL else int(j))]])
    str_lib.rawset("char", lambda *args: "".join(chr(int(a)) for a in args))
    str_lib.rawset("rep", lambda s="", n=0, sep="": (s + sep) * int(n))
    str_lib.rawset("lower", lambda s="": s.lower())
    str_lib.rawset("upper", lambda s="": s.upper())
    str_lib.rawset("reverse", lambda s="": s[::-1])
    str_lib.rawset("format", lambda fmt="", *args: fmt % tuple(args) if args else fmt)
    GLOBAL_ENV.rawset("string", str_lib)

    # Table library
    tbl_lib = LuaTable()
    def _tbl_insert(t=NIL, *args):
        if isinstance(t, LuaTable):
            if len(args) == 1:
                idx = 1
                while t.rawget(idx) is not NIL: idx += 1
                t.rawset(idx, args[0])
            elif len(args) == 2:
                pos, val = int(args[0]), args[1]
                idx = 1
                while t.rawget(idx) is not NIL: idx += 1
                for k in range(idx, pos, -1):
                    t.rawset(k, t.rawget(k-1))
                t.rawset(pos, val)
            return []
        raise LuaError("bad argument #1 to 'table.insert'")
    def _tbl_remove(t=NIL, pos=NIL):
        if isinstance(t, LuaTable):
            idx = 1
            while t.rawget(idx) is not NIL: idx += 1
            p = int(pos) if pos is not NIL else idx - 1
            val = t.rawget(p)
            for k in range(p, idx):
                t.rawset(k, t.rawget(k+1))
            return [val]
        raise LuaError("bad argument #1 to 'table.remove'")
    def _tbl_concat(t=NIL, sep="", i=1, j=NIL):
        if isinstance(t, LuaTable):
            if j is NIL:
                j = 0
                while t.rawget(j+1) is not NIL: j += 1
            elems = [lua_tostring(t.rawget(k)) for k in range(int(i), int(j)+1)]
            return [sep.join(elems)]
        raise LuaError("bad argument #1 to 'table.concat'")
    tbl_lib.rawset("insert", _tbl_insert)
    tbl_lib.rawset("remove", _tbl_remove)
    tbl_lib.rawset("concat", _tbl_concat)
    GLOBAL_ENV.rawset("table", tbl_lib)

    # Math library
    math_lib = LuaTable()
    math_lib.rawset("abs", math.abs if hasattr(math, 'abs') else lambda x: abs(x))
    math_lib.rawset("ceil", lambda x: math.ceil(x))
    math_lib.rawset("floor", lambda x: math.floor(x))
    math_lib.rawset("max", lambda *args: max(args) if args else NIL)
    math_lib.rawset("min", lambda *args: min(args) if args else NIL)
    math_lib.rawset("sin", math.sin)
    math_lib.rawset("cos", math.cos)
    math_lib.rawset("tan", math.tan)
    math_lib.rawset("sqrt", math.sqrt)
    math_lib.rawset("huge", float('inf'))
    math_lib.rawset("pi", math.pi)
    GLOBAL_ENV.rawset("math", math_lib)

    # Bit library
    bit_lib = LuaTable()
    def _tobit(x=0):
        v = int(x) & 0xffffffff
        return [v - 0x100000000 if v & 0x80000000 else v]
    def _tohex(x=0, n=8):
        v = int(x) & 0xffffffff
        return [f"{v:0{abs(int(n))}x}"]
    def _bnot(x=0): return [~int(x) & 0xffffffff]
    def _band(*args):
        res = 0xffffffff
        for a in args: res &= int(a)
        return [res & 0xffffffff]
    def _bor(*args):
        res = 0
        for a in args: res |= int(a)
        return [res & 0xffffffff]
