# --- CLI & MAIN DRIVER ---
def print_usage(prog):
    sys.stderr.write(
        f"usage: {prog} [options]... [script [args]...].\n"
        f"Available options are:\n"
        f"  -e chunk  Execute string 'chunk'.\n"
        f"  -l name   Require library 'name'.\n"
        f"  -b ...    Save or list bytecode.\n"
        f"  -j cmd    Perform LuaJIT control command.\n"
        f"  -O[opt]   Control LuaJIT optimizations.\n"
        f"  -i        Enter interactive mode after executing 'script'.\n"
        f"  -v        Show version information.\n"
        f"  -E        Ignore environment variables.\n"
        f"  --        Stop handling options.\n"
        f"  -         Execute stdin and stop handling options.\n"
    )
    sys.stderr.flush()

def main():
    argv = sys.argv
    prog = argv[0]

    actions = [] # ('e', chunk), ('l', name), ('j', cmd), ('O', opt)
    has_v = False
    has_i = False
    has_E = False
    script_idx = len(argv)
    script_file = None

    i = 1
    while i < len(argv):
        arg = argv[i]
        if not arg.startswith('-') or arg == '-':
            if arg == '-':
                script_file = '-'
                script_idx = i
                i += 1
            else:
                script_file = arg
                script_idx = i
            break

        if arg == '--':
            script_idx = i + 1
            if i + 1 < len(argv):
                script_file = argv[i + 1]
            break

        if arg.startswith('-E'):
            has_E = True
            i += 1
            continue

        if arg.startswith('-v'):
            if len(arg) == 2:
                has_v = True
                i += 1
                continue
            else:
                print_usage(prog)
                sys.exit(1)

        if arg.startswith('-i'):
            if len(arg) == 2:
                has_i = True
                i += 1
                continue
            else:
                print_usage(prog)
                sys.exit(1)

        if arg.startswith('-e'):
            val = arg[2:]
            if not val:
                i += 1
                if i >= len(argv):
                    print_usage(prog)
                    sys.exit(1)
                val = argv[i]
            actions.append(('e', val))
            i += 1
            continue

        if arg.startswith('-l'):
            val = arg[2:]
            if not val:
                i += 1
                if i >= len(argv):
                    print_usage(prog)
                    sys.exit(1)
                val = argv[i]
            actions.append(('l', val))
            i += 1
            continue

        if arg.startswith('-j'):
            val = arg[2:]
            if not val:
                i += 1
                if i >= len(argv):
                    print_usage(prog)
                    sys.exit(1)
                val = argv[i]
            actions.append(('j', val))
            i += 1
            continue

        if arg.startswith('-b'):
            sys.stderr.write(f"{prog}: unknown luaJIT command or jit.* modules not installed\n")
            sys.stderr.flush()
            sys.exit(1)

        if arg.startswith('-O'):
            val = arg[2:]
            actions.append(('O', val))
            i += 1
            continue

        # Unknown option
        print_usage(prog)
        sys.exit(1)

    # Build arg table
    arg_tbl = LuaTable()
    for idx, a in enumerate(argv):
        mapped_idx = idx - script_idx
        arg_tbl.rawset(mapped_idx, a)
    GLOBAL_ENV.rawset("arg", arg_tbl)

    # Environment variables
    if not has_E:
        lua_init = os.getenv("LUA_INIT")
        if lua_init:
            if lua_init.startswith('@'):
                fn = lua_init[1:]
                try:
                    _dofile(fn)
                except LuaError as e:
                    sys.stderr.write(f"{prog}: {e}\n")
                    sys.exit(1)
            else:
                try:
                    res = _loadstring(lua_init, "=(command line)")
                    if res[0] is not NIL:
                        lua_call(res[0], [])
                except LuaError as e:
                    sys.stderr.write(f"{prog}: {e}\n")
                    sys.exit(1)

    if has_v:
        sys.stdout.write(f"{LUAJIT_COPYRIGHT}\n")
        sys.stdout.flush()

    # Process actions in order
    for act_type, val in actions:
        if act_type == 'e':
            try:
                res = _loadstring(val, "(command line)")
                if res[0] is NIL:
                    sys.stderr.write(f"{prog}: {res[1]}\n")
                    sys.exit(1)
                lua_call(res[0], [])
            except LuaError as e:
                sys.stderr.write(f"{prog}: {e}\n")
                sys.exit(1)
        elif act_type == 'l':
            try:
                _require = GLOBAL_ENV.rawget("require")
                lua_call(_require, [val])
            except LuaError as e:
                sys.stderr.write(f"{prog}: {e}\n")
                sys.exit(1)
        elif act_type == 'j':
            if val in ('on', 'off', 'flush'):
                jit_fn = GLOBAL_ENV.rawget("jit").rawget(val)
                lua_call(jit_fn, [])
            elif val.startswith('opt='):
                pass
            elif val == 'opt':
                pass
            else:
                sys.stderr.write(f"{prog}: unknown luaJIT command or jit.* modules not installed\n")
                sys.exit(1)
        elif act_type == 'O':
            if val and val not in ('0', '1', '2', '3', ''):
                valid = False
                if val.startswith('-') or val.startswith('+') or '=' in val:
                    valid = True
                if not valid:
                    sys.stderr.write(f"{prog}: unknown or malformed optimization flag '{val}'\n")
                    sys.exit(1)

    if script_file is not None:
        try:
            res = _loadfile(script_file if script_file != '-' else None)
            if res[0] is NIL:
                sys.stderr.write(f"{prog}: {res[1]}\n")
                sys.exit(1)
            lua_call(res[0], [])
        except LuaError as e:
            sys.stderr.write(f"{prog}: {e}\n")
            sys.exit(1)
        except Exception as e:
            sys.stderr.write(f"{prog}: {e}\n")
            sys.exit(1)
        if has_i:
            run_interactive(prog, has_v)
    else:
        if not actions and not has_v:
            if sys.stdin.isatty() or has_i:
                run_interactive(prog, has_v)
            else:
                try:
                    res = _loadfile(None)
                    if res[0] is NIL:
                        sys.stderr.write(f"{prog}: {res[1]}\n")
                        sys.exit(1)
                    lua_call(res[0], [])
                except LuaError as e:
                    sys.stderr.write(f"{prog}: {e}\n")
                    sys.exit(1)
        elif has_i:
            run_interactive(prog, has_v)

def run_interactive(prog, has_v):
    if not has_v:
        sys.stdout.write(f"{LUAJIT_COPYRIGHT}\n")
    jit_status_fn = GLOBAL_ENV.rawget("jit").rawget("status")
    status_res = lua_call(jit_status_fn, [])
    st_str = "ON" if status_res[0] else "OFF"
    flags_str = " ".join(status_res[1:])
    sys.stdout.write(f"JIT: {st_str} {flags_str}\n")
    sys.stdout.flush()

    buf = ""
    prompt = "> "
    while True:
        try:
            sys.stdout.write(prompt)
            sys.stdout.flush()
            line = sys.stdin.readline()
            if not line:
                sys.stdout.write("\n")
                break
            if not buf and line.startswith('='):
                line = "print(" + line[1:].strip() + ")\n"
            buf += line
            res = _loadstring(buf, "=(command line)")
            if res[0] is not NIL:
                buf = ""
                prompt = "> "
                try:
                    lua_call(res[0], [])
                except LuaError as e:
                    sys.stderr.write(f"{e}\n")
                    sys.stderr.flush()
            else:
                if "unfinished" in str(res[1]) or "<eof>" in str(res[1]):
                    prompt = ">> "
                else:
                    sys.stderr.write(f"{res[1]}\n")
                    sys.stderr.flush()
                    buf = ""
                    prompt = "> "
        except (KeyboardInterrupt, EOFError):
            sys.stdout.write("\n")
            break

if __name__ == '__main__':
    main()
